function storage(): Storage | null {
  try {
    if (typeof localStorage === "undefined") return null;
    return localStorage;
  } catch {
    return null;
  }
}

function load(): Card[] {
  const ls = storage();
  if (!ls) return memory;
  try {
    const raw = ls.getItem(KEY);
    return raw ? (JSON.parse(raw) as Card[]) : [];
  } catch {
    return memory;
  }
}

